# Define the possible next digits based on the current digit
def possible_next_digits(current_digit):
    if current_digit == '1':
        return ['9']
    elif current_digit == '9':
        return ['3', '5']
    elif current_digit == '8':
        return ['3']
    elif current_digit == '7':
        return ['6']
    elif current_digit == '6':
        return ['2']
    elif current_digit == '5':
        return ['7', '3']
    elif current_digit == '4':
        return ['7']
    elif current_digit == '3':
        return []
    elif current_digit == '2':
        return []
    elif current_digit == '0':
        return []
    elif current_digit == '1':
        return []

# Generate the sequence
def generate_sequence(start_digit, length):
    sequence = [start_digit]
    for _ in range(1, length):
        next_digits = possible_next_digits(sequence[-1])
        if next_digits:
            sequence.append(next_digits[0])
        else:
            break
    return sequence

# Start with the first digit as 1 and generate the sequence of 2002 digits
sequence = generate_sequence('1', 2002)

# The last digit in the sequence
last_digit = sequence[-1]
print(last_digit)
